7	const BASE_PREMIUMS: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	  rune: 25,
13	  moonstone: 25,
14	};
15	
16	const FIRST_INSURANCE_SURCHARGE = 1.1;
17	const PROCESSING_FEE = 5;
18	
19	// Guards against binary-float artifacts (e.g. 52.800000000000004) tipping an
20	// exact value over a whole-gold boundary and inflating the premium by 1 G.
21	const FLOAT_ARTIFACT_PRECISION = 6;
22	
23	const roundUpToWholeGold = (amount: number): number =>
24	  Math.ceil(Number(amount.toFixed(FLOAT_ARTIFACT_PRECISION)));
25	
26	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
27	
28	const BUILDING_BLOCK_SIZE = 3;
29	const BUILDING_BLOCK_PREMIUM = 60;
30	
31	const areAlike = (items: Item[]): boolean =>
32	  items.every((item) => item.type === items[0].type);
33	
34	const totalBasePremiumOf = (items: Item[]): number => {
35	  if (!areAlike(items)) {
36	    return items.reduce((total, item) => total + basePremiumOf(item), 0);
37	  }
38	
39	  const blocks = Math.floor(items.length / BUILDING_BLOCK_SIZE);
40	  const loose = items.length % BUILDING_BLOCK_SIZE;
41	  return blocks * BUILDING_BLOCK_PREMIUM + loose * basePremiumOf(items[0]);
42	};
43	
44	const premiumFor = (step: Step): number =>
45	  roundUpToWholeGold(totalBasePremiumOf(step.items) * FIRST_INSURANCE_SURCHARGE) +
46	  PROCESSING_FEE;
47	
48	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
49	  results: [{ premium: premiumFor(scenario.steps[0]) }],
50	});
