const areAlike = (items: Item[]): boolean =>
  items.every((item) => item.type === items[0].type);

// Only alike items can be grouped into building blocks; an unalike list simply
// has none, and prices entirely as loose items.
const blockableCountOf = (items: Item[]): number => (areAlike(items) ? items.length : 0);

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((total, item) => total + basePremiumOf(item), 0);

const totalBasePremiumOf = (items: Item[]): number => {
  const blockable = blockableCountOf(items);
  const blocks = Math.floor(blockable / BUILDING_BLOCK_SIZE);
  const looseItems = items.slice(blocks * BUILDING_BLOCK_SIZE);

  return blocks * BUILDING_BLOCK_PREMIUM + sumOfBasePremiums(looseItems);
};
